type DeepWiden<T> = T extends string
	? string
	: T extends readonly [infer Head, ...infer Tail]
		? readonly [DeepWiden<Head>, ...DeepWiden<Tail>]
		: T extends readonly (infer Item)[]
			? readonly DeepWiden<Item>[]
			: T extends object
				? { readonly [Key in keyof T]: DeepWiden<T[Key]> }
				: T;

export type TranslationDictionary = DeepWiden<typeof vi>;

export const translations: Record<Locale, TranslationDictionary> = { vi, en, ja, zh };

function normalizeLocale(value: string | null | undefined): Locale | null {
	if (!value) return null;
	const candidate = value.toLowerCase().split("-")[0];
	return (locales as readonly string[]).includes(candidate) ? (candidate as Locale) : null;
}

export function getTranslation(locale?: string | null): TranslationDictionary {
	return translations[normalizeLocale(locale) ?? defaultLocale];
}

export function formatProjectCount(locale: Locale, count: number): string {
	const template = getTranslation(locale).work.projectCount[new Intl.PluralRules(locale).select(count) === "one" ? "one" : "other"];
	return template.replace("{count}", new Intl.NumberFormat(locale).format(count));
}

export function localizePath(path: string, locale: Locale = defaultLocale): string {
	const match = path.match(/^([^?#]*)(.*)$/);
	const pathname = match?.[1] || "/";
	const suffix = match?.[2] || "";
	const normalized = pathname.startsWith("/") ? pathname : `/${pathname}`;
	const withoutLocale = normalized.replace(/^\/(?:vi|en|ja|zh)(?=\/|$)/, "") || "/";
	const localized = locale === defaultLocale ? withoutLocale : `/${locale}${withoutLocale === "/" ? "" : withoutLocale}`;
	return `${localized || "/"}${suffix}`;
}
